    Y, X = grid(h, w)
    l = 0.5 + 0.5 * np.cos((X - 0.2) * 2 * math.pi) * np.sin(Y * math.pi)
    img = ramp(l, [(0, '#2fc4ff'), (0.6, '#a6f6ff'), (1, '#ffffff')])
    return clamp(img)


