# ------------------------------------------------------------ HAIRDRYER ---
def tex_dryer_shell():
    # glossy hot-pink salon plastic with a soft studio highlight band
    return enamel('#e8336a', 281, flake=0.15, chips=False, gloss=0.32)


def tex_dryer_metal():
    return chrome(282, tint=(1.04, 1.0, 0.97))


def tex_dryer_inner():
    return clamp(brushed(283, col='#2b2d31') * 0.8)


def tex_dryer_grip():
    return rubber(284, col='#1b1c20', knurl=True)


def tex_dryer_switch():
    return plastic('#ffcf2e', 285, grain=0.05)


def tex_dryer_grille():
    h = w = S
    Y, X = grid(h, w)
    r = np.sqrt((X - 0.5) ** 2 + (Y - 0.5) ** 2) * 2
    a = np.arctan2(Y - 0.5, X - 0.5)
    slots = 0.5 + 0.5 * np.cos(r * 2 * math.pi * 7)
    ribs = 0.5 + 0.5 * np.cos(a * 12)
    hole = smoothstep(0.55, 0.7, slots) * smoothstep(0.35, 0.55, ribs) * smoothstep(0.98, 0.9, r) * smoothstep(0.12, 0.2, r)
    land = ramp(clamp(Y + 0.1 * (fbm(h, w, 3, 3, 286) - 0.5)), [(0, '#e9eef5'), (0.45, '#8a929d'), (0.55, '#3a3f46'), (1, '#c3c9d1')])
    img = lerp(land, hexc('#08090b'), hole)
    hub = smoothstep(0.14, 0.1, r)
    img = lerp(img, hexc('#e8336a'), hub)
    return clamp(img)


def tex_dryer_coil():
    h = w = S
    Y, X = grid(h, w)
    n = fbm(h, w, 4, 4, 287) - 0.5
    band = 0.5 + 0.5 * np.sin((X * 9 + n * 0.6) * 2 * math.pi)
    heat = clamp(0.55 + 0.35 * band + 0.3 * n)
    img = ramp(heat, [(0.0, '#7a0a00'), (0.35, '#e0260a'), (0.65, '#ff7a1c'), (0.88, '#ffd36a'), (1.0, '#fffbe8')])
    return clamp(img)


def all_textures():
    """name -> callable producing an image. Names are paths under textures/."""
    T = {
        'block/gola_enamel': tex_gola_enamel, 'block/gola_chrome': tex_gola_chrome, 'block/gola_rubber': tex_gola_rubber,
        'block/gola_badge': tex_gola_badge,
        'block/fan_body': tex_fan_body, 'block/fan_panel': tex_fan_panel, 'block/fan_blade': tex_fan_blade,
        'block/fan_keys': tex_fan_keys, 'block/fan_nameplate': tex_fan_nameplate,
        'block/ac_body': tex_ac_body, 'block/ac_bracket': tex_ac_bracket, 'block/ac_grille': tex_ac_grille,
        'block/ac_sticker': tex_ac_sticker,
        'block/fridge_liner': tex_fridge_liner, 'block/fridge_freezer': tex_fridge_freezer,
        'block/fridge_gasket': tex_fridge_gasket, 'block/fridge_light': tex_fridge_light, 'block/fridge_bin': tex_fridge_bin,
        'block/fridge_bottle': tex_fridge_bottle,
        'block/cone_waffle': tex_cone_waffle, 'block/icecream_swirl': tex_icecream_swirl, 'block/cone_cherry': tex_cone_cherry,
        'block/sprinkles': tex_sprinkles, 'block/truck_sign': tex_truck_sign, 'block/truck_glass': tex_truck_glass, 'block/truck_menu': tex_truck_menu,
        'block/portal_crystal': tex_portal_crystal, 'block/portal_core': tex_portal_core,
        'block/portal_icicle': tex_portal_icicle, 'block/portal_glow': tex_portal_glow,
        'block/pedestal_ice': tex_pedestal_ice, 'block/pedestal_glow': tex_pedestal_glow,
        'block/chandelier_metal': tex_chandelier_metal, 'block/chandelier_glow': tex_chandelier_glow,
        'block/remote_body': tex_remote_body, 'block/remote_face': tex_remote_face, 'block/remote_bezel': tex_remote_bezel,
        'block/remote_lcd': tex_remote_lcd, 'block/remote_power': tex_remote_power, 'block/remote_button': tex_remote_button,
        'block/remote_keys': tex_remote_keys, 'block/orb_vortex': tex_orb_vortex,
        'block/frost_bricks': tex_frost_bricks, 'block/frosted_glass': tex_frosted_glass, 'block/permafrost_ice': tex_permafrost_ice,
        'block/glacier_tiles': tex_glacier_tiles, 'block/aurora_ice': tex_aurora_ice, 'block/packed_frost': tex_packed_frost,
        'block/ice_pillar_side': tex_ice_pillar_side, 'block/ice_pillar_top': tex_ice_pillar_top,
        'block/snow_floor': tex_snow_floor,
        'block/dryer_shell': tex_dryer_shell, 'block/dryer_metal': tex_dryer_metal, 'block/dryer_inner': tex_dryer_inner,
        'block/dryer_grip': tex_dryer_grip, 'block/dryer_switch': tex_dryer_switch, 'block/dryer_grille': tex_dryer_grille,
        'block/dryer_coil': tex_dryer_coil,
        'entity/frost_vortex': tex_frost_vortex, 'entity/glow_halo': tex_glow_halo, 'entity/light_beam': tex_light_beam,
        'gui/shop_panel': lambda: gui_panel(512, 320), 'gui/card': gui_card,
        'gui/button_normal': lambda: gui_button(state='normal'), 'gui/button_hover': lambda: gui_button(state='hover'),
        'gui/button_locked': lambda: gui_button(state='locked'), 'gui/button_owned': lambda: gui_button(state='owned'),
        'gui/hud_panel': gui_hud_panel, 'gui/counter_bar': gui_counter_bar, 'gui/ice_cube': gui_ice_cube, 'gui/remote_lcd': gui_remote_lcd,
        'gui/progress': gui_progress,
        'item/chill_villager_spawn_egg': tex_chill_villager_egg, 'item/ice_cream_van_spawn_egg': tex_van_egg,
    }
    for kind in ('frost_swirl', 'ice_shard', 'snowflake', 'frost_mist', 'sparkle'):
        for name, img in particle_set(kind).items():
            T['particle/' + name] = (lambda im=img: im)
    return T


