def sounds_json():
    out = {}
    for s in SOUNDS_CUSTOM:
        entry = {"name": f"{MODID}:{s}"}
        if s == 'van_jingle':
            entry["stream"] = True
        out[s] = {"subtitle": f"subtitles.{MODID}.{s}", "sounds": [entry]}
    out['villager_scream'] = {"subtitle": f"subtitles.{MODID}.villager_scream", "sounds": [
        {"name": "minecraft:mob/villager/hit1", "pitch": 1.55, "volume": 1.0},
        {"name": "minecraft:mob/villager/hit2", "pitch": 1.6, "volume": 1.0},
        {"name": "minecraft:mob/villager/hit3", "pitch": 1.7, "volume": 1.0},
        {"name": "minecraft:mob/villager/hit4", "pitch": 1.5, "volume": 1.0}]}
    out['villager_relief'] = {"subtitle": f"subtitles.{MODID}.villager_relief", "sounds": [
        {"name": "minecraft:mob/villager/yes1", "pitch": 0.72, "volume": 0.9},
        {"name": "minecraft:mob/villager/yes2", "pitch": 0.7, "volume": 0.9},
        {"name": "minecraft:mob/villager/idle2", "pitch": 0.68, "volume": 0.9}]}
    out['fridge_rattle'] = {"subtitle": f"subtitles.{MODID}.fridge_rattle", "sounds": [
        {"name": "minecraft:block/chain/break1", "pitch": 1.3}, {"name": "minecraft:block/chain/break2", "pitch": 1.2},
        {"name": "minecraft:block/iron_door/close1", "pitch": 1.4, "volume": 0.6}]}
    return out


def lang():
    d = dict(LANG)
    for k, v in SUBTITLES.items():
        d[f"subtitles.{MODID}.{k}"] = v
    return d


def obj_model_json(obj_rel, mats, particle, render_type='minecraft:cutout', display=None):
    tex = {"particle": f"{MODID}:{particle}"}
    for m in mats:
        tex[m] = f"{MODID}:block/{TEXTURE_ALIAS.get(m, m)}"
    j = {"loader": "forge:obj", "model": f"{MODID}:models/{obj_rel}", "flip_v": False, "emissive_ambient": True,
         "automatic_culling": False, "shade_quads": True, "ambientocclusion": False, "render_type": render_type, "textures": tex}
    if display:
        j["display"] = display
    return j


def write_static_resources(res):
    A = os.path.join(res, 'assets', MODID)
    D = os.path.join(res, 'data', MODID)
    write(os.path.join(res, 'META-INF', 'mods.toml'), MODS_TOML)
    write_json(os.path.join(res, 'pack.mcmeta'), {"pack": {"description": {"text": "Ice Age Yantra resources"}, "pack_format": 15}})
    write_json(os.path.join(A, 'lang', 'en_us.json'), lang())
    write_json(os.path.join(A, 'sounds.json'), sounds_json())
    write(os.path.join(A, 'CREDITS.txt'), CREDITS)

    # ---- blockstates + block models
    def facing_variants(model, extra=''):
        v = {}
        for f, y in (('north', 0), ('east', 90), ('south', 180), ('west', 270)):
            key = f"facing={f}" + extra
            v[key] = {"model": model} if y == 0 else {"model": model, "y": y}
        return v

    particles = {'gola_machine': 'block/gola_enamel', 'farrata_fan': 'block/fan_body', 'retro_fridge': 'block/fridge_liner',
                 'ac_unit': 'block/ac_body'}
    for b, p in particles.items():
        write_json(os.path.join(A, 'models', 'block', b + '.json'), {"textures": {"particle": f"{MODID}:{p}"}})
        if b == 'retro_fridge':
            v = {}
            for half in ('lower', 'upper'):
                v.update(facing_variants(f"{MODID}:block/{b}", f",half={half}"))
            write_json(os.path.join(A, 'blockstates', b + '.json'), {"variants": v})
        else:
            write_json(os.path.join(A, 'blockstates', b + '.json'), {"variants": facing_variants(f"{MODID}:block/{b}")})
    # portal (lower: OBJ frame, upper: particles only)
    write_json(os.path.join(A, 'models', 'block', 'ice_portal_upper.json'), {"textures": {"particle": f"{MODID}:block/portal_crystal"}})
    v = {}
    v.update(facing_variants(f"{MODID}:block/ice_portal", ",half=lower"))
    v.update(facing_variants(f"{MODID}:block/ice_portal_upper", ",half=upper"))
    write_json(os.path.join(A, 'blockstates', 'ice_portal.json'), {"variants": v})
    write_json(os.path.join(A, 'blockstates', 'showcase_pedestal.json'),
               {"variants": {f"tier={t}": {"model": f"{MODID}:block/showcase_pedestal"} for t in range(1, 6)}})
    write_json(os.path.join(A, 'blockstates', 'icicle_chandelier.json'), {"variants": {"": {"model": f"{MODID}:block/icicle_chandelier"}}})
    write_json(os.path.join(A, 'models', 'block', 'shop_sign.json'), {"textures": {"particle": f"{MODID}:block/aurora_ice"}})
    write_json(os.path.join(A, 'blockstates', 'shop_sign.json'), {"variants": {"": {"model": f"{MODID}:block/shop_sign"}}})
    for b in DECOR:
        m = {"parent": "minecraft:block/cube_all", "textures": {"all": f"{MODID}:block/{b}"}}
        if b in ('frosted_glass', 'permafrost_ice'):
            m["render_type"] = "minecraft:translucent"
        write_json(os.path.join(A, 'models', 'block', b + '.json'), m)
        write_json(os.path.join(A, 'blockstates', b + '.json'), {"variants": {"": {"model": f"{MODID}:block/{b}"}}})
        write_json(os.path.join(A, 'models', 'item', b + '.json'), {"parent": f"{MODID}:block/{b}"})
    write_json(os.path.join(A, 'models', 'block', 'ice_pillar.json'),
               {"parent": "minecraft:block/cube_column", "textures": {"end": f"{MODID}:block/ice_pillar_top", "side": f"{MODID}:block/ice_pillar_side"}})
    write_json(os.path.join(A, 'models', 'block', 'ice_pillar_horizontal.json'),
               {"parent": "minecraft:block/cube_column_horizontal", "textures": {"end": f"{MODID}:block/ice_pillar_top", "side": f"{MODID}:block/ice_pillar_side"}})
    write_json(os.path.join(A, 'blockstates', 'ice_pillar.json'), {"variants": {
        "axis=y": {"model": f"{MODID}:block/ice_pillar"},
        "axis=z": {"model": f"{MODID}:block/ice_pillar_horizontal", "x": 90},
        "axis=x": {"model": f"{MODID}:block/ice_pillar_horizontal", "x": 90, "y": 90}}})
    write_json(os.path.join(A, 'models', 'item', 'ice_pillar.json'), {"parent": f"{MODID}:block/ice_pillar"})

    # ---- item models
    for it in YANTRA_ITEMS:
        p = particles.get(it, 'block/truck_sign')
        write_json(os.path.join(A, 'models', 'item', it + '.json'),
                   {"parent": "builtin/entity", "gui_light": "side", "textures": {"particle": f"{MODID}:{p}"}, "display": BLOCK_DISPLAY})
    for egg in ('chill_villager_spawn_egg', 'ice_cream_van_spawn_egg'):
        write_json(os.path.join(A, 'models', 'item', egg + '.json'),
                   {"parent": "minecraft:item/generated", "textures": {"layer0": f"{MODID}:item/{egg}"}})

    # ---- particles
    frames = {'frost_swirl': 8, 'ice_shard': 4, 'snowflake': 4, 'frost_mist': 4, 'sparkle': 4}
    for p, n in frames.items():
        write_json(os.path.join(A, 'particles', p + '.json'), {"textures": [f"{MODID}:{p}_{i}" for i in range(n)]})

    # ---- loot tables
    def drop_self(name, cond=None):
        entry = {"type": "minecraft:item", "name": f"{MODID}:{name}"}
        pool = {"rolls": 1, "entries": [entry], "conditions": [{"condition": "minecraft:survives_explosion"}]}
        if cond:
            pool["conditions"].append(cond)
        return {"type": "minecraft:block", "pools": [pool]}
    for b in ['gola_machine', 'farrata_fan', 'ac_unit', 'icicle_chandelier', 'ice_pillar'] + DECOR:
        write_json(os.path.join(D, 'loot_tables', 'blocks', b + '.json'), drop_self(b))
    lower = {"condition": "minecraft:block_state_property", "block": f"{MODID}:retro_fridge", "properties": {"half": "lower"}}
    write_json(os.path.join(D, 'loot_tables', 'blocks', 'retro_fridge.json'), drop_self('retro_fridge', lower))
    lower_p = {"condition": "minecraft:block_state_property", "block": f"{MODID}:ice_portal", "properties": {"half": "lower"}}
    write_json(os.path.join(D, 'loot_tables', 'blocks', 'ice_portal.json'), drop_self('ice_portal', lower_p))

    # ---- tags
    pick = [f"{MODID}:{b}" for b in ['gola_machine', 'farrata_fan', 'retro_fridge', 'ac_unit', 'ice_portal', 'icicle_chandelier',
                                      'permafrost_ice', 'frost_bricks', 'glacier_tiles', 'aurora_ice', 'packed_frost', 'ice_pillar', 'frosted_glass']]
    write_json(os.path.join(res, 'data', 'minecraft', 'tags', 'blocks', 'mineable', 'pickaxe.json'), {"replace": False, "values": pick})
    write_json(os.path.join(res, 'data', 'minecraft', 'tags', 'blocks', 'mineable', 'shovel.json'),
               {"replace": False, "values": [f"{MODID}:snow_floor"]})

    # ---- frozen showroom dimension
    write_json(os.path.join(D, 'dimension_type', 'frozen_showroom.json'), {
        "ultrawarm": False, "natural": False, "coordinate_scale": 1.0, "has_skylight": False, "has_ceiling": False,
        "ambient_light": 0.4, "fixed_time": 6000, "monster_spawn_light_level": 0, "monster_spawn_block_light_limit": 0,
        "piglin_safe": False, "bed_works": False, "respawn_anchor_works": False, "has_raids": False, "logical_height": 256,
        "min_y": 0, "height": 256, "infiniburn": "#minecraft:infiniburn_overworld", "effects": "minecraft:overworld"})
    write_json(os.path.join(D, 'dimension', 'frozen_showroom.json'), {
        "type": f"{MODID}:frozen_showroom",
        "generator": {"type": "minecraft:flat", "settings": {"biome": f"{MODID}:frozen_showroom", "lakes": False,
                                                             "features": False, "layers": [], "structure_overrides": []}}})
    write_json(os.path.join(D, 'worldgen', 'biome', 'frozen_showroom.json'), {
        "has_precipitation": False, "temperature": -0.7, "downfall": 0.4,
        "effects": {"fog_color": 0xBFE6FF, "sky_color": 0x8FD3FF, "water_color": 0x3F76E4, "water_fog_color": 0x050533,
                    "particle": {"options": {"type": "minecraft:snowflake"}, "probability": 0.0035}},
        "spawners": {}, "spawn_costs": {}, "carvers": {}, "features": []})


# ------------------------------------------------------------ models + tex ---
def build_models(res, models_dir, rig_out):
    """Builds every rig, writes OBJ/MTL + model JSON, returns (pivots, texture requests)."""
    A = os.path.join(res, 'assets', MODID)
    pivots = {}
    orig = {}
    jobs = []
    for key, fname in SOURCE_MODELS.items():
        path = os.path.join(models_dir, fname)
        if not os.path.exists(path):
            raise SystemExit(f"Missing source model {path}. Put the 5 Sketchfab zips into {models_dir} (see README).")
        jobs.append((key, path))
    rigs = []
    for key, path in jobs:
        t = time.time()
        rig = globals()['build_' + key](path)
        log(f"rig {key}: {sum(len(s.P) for s in rig.all_surfs())} tris ({time.time() - t:.1f}s)")
        rigs.append(rig)
    for fn in (build_portal_frame, build_pedestal, build_chandelier, build_remote, build_shop_orb, build_hairdryer):
        t = time.time()
        rig = fn()
        log(f"rig {rig.name}: {sum(len(s.P) for s in rig.all_surfs())} tris ({time.time() - t:.1f}s)")
        rigs.append(rig)
    for rig in rigs:
        for name, piv in rig.pivots.items():
            pivots[f"{rig.name}_{name}"] = piv
        orig.update(rig.orig_textures)
        for part, surfs in rig.parts.items():
            mats = sorted({s.mat for s in surfs})
            obj_rel = f"obj/{rig.name}/{part}.obj"
            obj_path = os.path.join(A, 'models', obj_rel)
            write_obj(obj_path, surfs, part + '.mtl', {m: '#' + m for m in mats},
                      header=f"Ice Age Yantra - {rig.name}/{part} (generated)", emissive=rig.emissive)
            particle = 'block/' + TEXTURE_ALIAS.get(mats[0], mats[0])
            rig_out.add(f"{rig.name}_{part}")
            write_json(os.path.join(A, 'models', 'block', 'rig', f"{rig.name}_{part}.json"), obj_model_json(obj_rel, mats, particle))
    # static block / item models built from procedural rigs
    mats_of = {r.name: sorted({s.mat for v in r.parts.values() for s in v}) for r in rigs}
    write_json(os.path.join(A, 'models', 'block', 'ice_portal.json'),
               obj_model_json("obj/portal/frame.obj", mats_of['portal'], 'block/portal_crystal'))
    write_json(os.path.join(A, 'models', 'item', 'ice_portal.json'),
               obj_model_json("obj/portal/frame.obj", mats_of['portal'], 'block/portal_crystal', display=PORTAL_ITEM_DISPLAY))
    write_json(os.path.join(A, 'models', 'block', 'showcase_pedestal.json'),
               obj_model_json("obj/pedestal/base.obj", mats_of['pedestal'], 'block/pedestal_ice'))
    write_json(os.path.join(A, 'models', 'item', 'showcase_pedestal.json'),
               obj_model_json("obj/pedestal/base.obj", mats_of['pedestal'], 'block/pedestal_ice', display=BLOCK_DISPLAY))
    write_json(os.path.join(A, 'models', 'block', 'icicle_chandelier.json'),
               obj_model_json("obj/chandelier/base.obj", mats_of['chandelier'], 'block/chandelier_glow'))
    write_json(os.path.join(A, 'models', 'item', 'icicle_chandelier.json'),
               obj_model_json("obj/chandelier/base.obj", mats_of['chandelier'], 'block/chandelier_glow', display=BLOCK_DISPLAY))
    write_json(os.path.join(A, 'models', 'item', 'ac_remote.json'),
               obj_model_json("obj/remote/base.obj", mats_of['remote'], 'block/remote_body', display=HAND_DISPLAY))
    write_json(os.path.join(A, 'models', 'item', 'yantra_shop_portal.json'),
               obj_model_json("obj/shop_orb/base.obj", mats_of['shop_orb'], 'block/portal_crystal', display=ORB_DISPLAY))
    return pivots, orig, rigs


def write_textures(res, orig):
    A = os.path.join(res, 'assets', MODID, 'textures')
    T = all_textures()
    t0 = time.time()
    for name, fn in T.items():
        save_png(os.path.join(A, name + '.png'), fn())
    # textures derived from the source models
    if 'fridge_main' in orig:
        save_png(os.path.join(A, 'block', 'fridge_main.png'), bake_fridge_main(*orig['fridge_main'], size=1024))
    if 'fridge_back' in orig:
        save_png(os.path.join(A, 'block', 'fridge_back.png'), bake_fridge_main(*orig['fridge_back'], size=512))
    if 'truck_paint' in orig:
        save_png(os.path.join(A, 'block', 'truck_paint.png'), bake_truck_paint(orig['truck_paint'], size=1024))
    if 'ac_fan' in orig:
        img = resize(from_pil(orig['ac_fan']), 512, 512)
        save_png(os.path.join(A, 'block', 'ac_fan.png'), clamp(img * 1.15 + 0.03))
    log(f"textures: {len(T) + 4} written ({time.time() - t0:.1f}s)")


def rig_java(pivots):
    lines = ["package com.iceage.yantra;", "", "/** Generated by build_ice_age_mod.py: pivots of the baked OBJ rigs (block units). */",
             "public final class RigData {"]
    for k in sorted(pivots):
        x, y, z = pivots[k]
        n = k.upper()
        lines.append(f"    public static final double {n}_X = {x:.6f}, {n}_Y = {y:.6f}, {n}_Z = {z:.6f};")
    lines += ["", "    private RigData() {", "    }", "}", ""]
    return '\n'.join(lines)


def write_embedded(out):
    for rel, text in JAVA_SOURCES.items():
        write(os.path.join(out, rel), text)
    for name, b64 in SOUNDS_B64.items():
        write(os.path.join(out, 'src', 'main', 'resources', 'assets', MODID, 'sounds', name + '.ogg'),
              zlib.decompress(base64.b64decode(b64)), binary=True)
    write(os.path.join(out, 'gradle', 'wrapper', 'gradle-wrapper.jar'), base64.b64decode(GRADLE_WRAPPER_JAR_B64), binary=True)
    write(os.path.join(out, 'gradlew'), GRADLEW_SH)
    os.chmod(os.path.join(out, 'gradlew'), 0o755)
    write(os.path.join(out, 'gradlew.bat'), GRADLEW_BAT.replace('\n', '\r\n'))


def main(argv=None):
    here = os.path.dirname(os.path.abspath(__file__))
    ap = argparse.ArgumentParser(description='Generate the Ice Age Yantra Forge 1.20.1 mod project.')
    ap.add_argument('--out', default=os.path.join(here, 'ice_age_yantra'), help='output project directory')
    ap.add_argument('--models', default=os.path.join(here, 'source_models'), help='folder with the 5 Sketchfab .zip models')
    ap.add_argument('--clean', action='store_true', help='delete the output folder first')
    a = ap.parse_args(argv)
    out = os.path.abspath(a.out)
    if a.clean and os.path.isdir(out):
        shutil.rmtree(out)
    log(f"generating {MOD_NAME} into {out}")
    write(os.path.join(out, 'build.gradle'), BUILD_GRADLE)
    write(os.path.join(out, 'settings.gradle'), SETTINGS_GRADLE)
    write(os.path.join(out, 'gradle.properties'), GRADLE_PROPERTIES)
    write(os.path.join(out, 'gradle', 'wrapper', 'gradle-wrapper.properties'), WRAPPER_PROPERTIES)
    write(os.path.join(out, '.gitignore'), GITIGNORE)
    write_embedded(out)
    res = os.path.join(out, 'src', 'main', 'resources')
    write_static_resources(res)
    rig_parts = set()
    pivots, orig, _ = build_models(res, os.path.abspath(a.models), rig_parts)
    write(os.path.join(out, 'src', 'main', 'java', 'com', 'iceage', 'yantra', 'RigData.java'), rig_java(pivots))
    write_textures(res, orig)
    log("done. Now run:  cd " + out + " && ./gradlew build   (jar in build/libs/)")


