JAVA_SOURCES['src/main/java/com/iceage/yantra/progress/FreezeEngine.java'] = r'''package com.iceage.yantra.progress;

import com.iceage.yantra.Config;
import com.iceage.yantra.IceAgeYantra;
import com.iceage.yantra.registry.ModBlocks;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.tags.BlockTags;
import net.minecraft.tags.FluidTags;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.LiquidBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.material.FluidState;
import net.minecraft.world.level.material.Fluids;
import net.minecraftforge.registries.ForgeRegistries;

/**
 * Frost chain: natural block -> Permafrost Ice -> packed ice -> blue ice. Every step that changes the world is
 * one frozen block for the pacing engine. ICE MUST NEVER MELT: vanilla ice / frosted ice / snow layers are
 * never produced - only Permafrost Ice (no random ticks), packed ice and blue ice, none of which can melt.
 */
public final class FreezeEngine {
    public static final int NATURAL = 0, ICE = 1, PACKED = 2, BLUE = 3;
    private static final int FLAGS = Block.UPDATE_CLIENTS | Block.UPDATE_KNOWN_SHAPE;

    private FreezeEngine() {
    }

    public static int stageOf(BlockState s) {
        if (s.is(Blocks.BLUE_ICE)) return BLUE;
        if (s.is(Blocks.PACKED_ICE)) return PACKED;
        if (s.is(ModBlocks.PERMAFROST_ICE.get())) return ICE;
        return NATURAL;
    }

    /** Never returns a meltable block. */
    public static BlockState stateFor(int stage) {
        return switch (stage) {
            case ICE -> ModBlocks.PERMAFROST_ICE.get().defaultBlockState();
            case PACKED -> Blocks.PACKED_ICE.defaultBlockState();
            default -> Blocks.BLUE_ICE.defaultBlockState();
        };
    }

    public static boolean isModBlock(BlockState s) {
        if (s.is(ModBlocks.PERMAFROST_ICE.get())) return false;
        var key = ForgeRegistries.BLOCKS.getKey(s.getBlock());
        return key != null && IceAgeYantra.MODID.equals(key.getNamespace());
    }

    /** Blocks that must never be touched (bedrock-like, containers, our own machines, portals). */
    public static boolean isProtected(Level level, BlockPos pos, BlockState s) {
        if (s.isAir()) return true;
        if (s.getDestroySpeed(level, pos) < 0) return true;
        if (Config.PROTECT_CONTAINERS.get() && s.hasBlockEntity()) return true;
        if (s.is(Blocks.NETHER_PORTAL) || s.is(Blocks.END_PORTAL) || s.is(Blocks.END_GATEWAY)) return true;
        return isModBlock(s);
    }

    public static boolean isPlant(BlockState s) {
        return s.getFluidState().isEmpty() && (s.canBeReplaced() || s.is(BlockTags.FLOWERS) || s.is(BlockTags.SAPLINGS)
                || s.is(BlockTags.CROPS) || s.is(Blocks.SWEET_BERRY_BUSH) || s.is(Blocks.SUGAR_CANE));
    }

    /** Advance one step along the frost chain, never beyond maxStage. Returns 1 when the world changed. */
    public static int advance(ServerLevel level, BlockPos pos, int maxStage) {
        BlockState s = level.getBlockState(pos);
        if (s.isAir()) return 0;
        FluidState f = s.getFluidState();
        if (s.getBlock() instanceof LiquidBlock) {
            if (f.is(FluidTags.WATER)) {
                level.setBlock(pos, stateFor(Math.max(ICE, Math.min(maxStage, PACKED))), FLAGS);
                return 1;
            }
            if (f.is(FluidTags.LAVA)) {
                level.setBlock(pos, f.isSource() ? Blocks.OBSIDIAN.defaultBlockState() : Blocks.COBBLESTONE.defaultBlockState(), FLAGS);
                return 1;
            }
            return 0;
        }
        if (isPlant(s)) {
            level.setBlock(pos, Blocks.AIR.defaultBlockState(), FLAGS);
            return 1;
        }
        if (isProtected(level, pos, s)) return 0;
        if (s.hasProperty(net.minecraft.world.level.block.state.properties.BlockStateProperties.WATERLOGGED)
                && s.getValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.WATERLOGGED)) {
            level.setBlock(pos, stateFor(Math.max(ICE, Math.min(maxStage, PACKED))), FLAGS);
            return 1;
        }
        int st = stageOf(s);
        if (st >= maxStage) return 0;
        int next = st + 1;
        if (st == NATURAL && (s.is(BlockTags.LEAVES) || s.is(BlockTags.LOGS))) next = Math.min(maxStage, ICE);
        level.setBlock(pos, stateFor(next), FLAGS);
        return 1;
    }

    /** Convert straight to a stage (used by the van / AC). Returns 1 when the world changed. */
    public static int freezeTo(ServerLevel level, BlockPos pos, int stage) {
        BlockState s = level.getBlockState(pos);
        if (s.isAir()) return 0;
        if (s.getBlock() instanceof LiquidBlock) {
            FluidState f = s.getFluidState();
            if (f.is(FluidTags.LAVA)) {
                level.setBlock(pos, Blocks.OBSIDIAN.defaultBlockState(), FLAGS);
                return 1;
            }
            level.setBlock(pos, stateFor(Math.max(stage, ICE)), FLAGS);
            return 1;
        }
        if (isPlant(s)) {
            level.setBlock(pos, Blocks.AIR.defaultBlockState(), FLAGS);
            return 1;
        }
        if (isProtected(level, pos, s)) return 0;
        if (stageOf(s) >= stage) return 0;
        level.setBlock(pos, stateFor(stage), FLAGS);
        return 1;
    }

    /** Removes a block (the van plough). Returns 1 when something was shattered. */
    public static int shatter(ServerLevel level, BlockPos pos) {
        BlockState s = level.getBlockState(pos);
        if (s.isAir()) return 0;
        if (s.getBlock() instanceof LiquidBlock) {
            level.setBlock(pos, Blocks.AIR.defaultBlockState(), FLAGS);
            return 1;
        }
        if (isProtected(level, pos, s)) return 0;
        level.setBlock(pos, Blocks.AIR.defaultBlockState(), FLAGS);
        return 1;
    }

    /** Top solid ground block of a column, searched downward from y+up to y-down. */
    public static BlockPos surface(Level level, int x, int z, int y, int up, int down) {
        BlockPos.MutableBlockPos m = new BlockPos.MutableBlockPos(x, y + up, z);
        for (int i = 0; i <= up + down; i++) {
            BlockState s = level.getBlockState(m);
            if (!s.isAir() && !isPlant(s)) {
                return m.immutable();
            }
            m.move(0, -1, 0);
        }
        return null;
    }

    public static boolean isFluidSource(BlockState s) {
        return s.getFluidState().isSource() && s.getFluidState().getType() != Fluids.EMPTY;
    }
}
'''
JAVA_SOURCES['src/main/java/com/iceage/yantra/progress/IceProgress.java'] = r'''package com.iceage.yantra.progress;

import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.resources.ResourceKey;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraft.world.phys.Vec3;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/** World-wide persistent progress: frozen blocks per player, purchases, showroom return points. */
public class IceProgress extends SavedData {
    public static final String NAME = "ice_age_yantra_progress";

    public static class Entry {
        public long points;
        public int purchasedMask;
        public boolean portalGiven;
        public boolean climaxDone;
        public float speed = 1.0f;
        public ResourceKey<Level> returnDim;
        public Vec3 returnPos;
        public float returnYaw;

        CompoundTag save() {
            CompoundTag t = new CompoundTag();
            t.putLong("points", points);
            t.putInt("purchased", purchasedMask);
            t.putBoolean("portalGiven", portalGiven);
            t.putBoolean("climax", climaxDone);
            t.putFloat("speed", speed);
            if (returnDim != null && returnPos != null) {
                t.putString("rdim", returnDim.location().toString());
                t.putDouble("rx", returnPos.x);
                t.putDouble("ry", returnPos.y);
                t.putDouble("rz", returnPos.z);
                t.putFloat("ryaw", returnYaw);
            }
            return t;
        }

        @SuppressWarnings("removal")
        static Entry load(CompoundTag t) {
            Entry e = new Entry();
            e.points = t.getLong("points");
            e.purchasedMask = t.getInt("purchased");
            e.portalGiven = t.getBoolean("portalGiven");
            e.climaxDone = t.getBoolean("climax");
            e.speed = t.contains("speed") ? t.getFloat("speed") : 1.0f;
            if (t.contains("rdim")) {
                e.returnDim = ResourceKey.create(Registries.DIMENSION, new ResourceLocation(t.getString("rdim")));
                e.returnPos = new Vec3(t.getDouble("rx"), t.getDouble("ry"), t.getDouble("rz"));
                e.returnYaw = t.getFloat("ryaw");
            }
            return e;
        }
    }

    private final Map<UUID, Entry> entries = new HashMap<>();

    public static IceProgress get(MinecraftServer server) {
        return server.overworld().getDataStorage().computeIfAbsent(IceProgress::load, IceProgress::new, NAME);
    }

    public Entry entry(UUID id) {
        return entries.computeIfAbsent(id, k -> new Entry());
    }

    public static IceProgress load(CompoundTag tag) {
        IceProgress p = new IceProgress();
        ListTag list = tag.getList("players", Tag.TAG_COMPOUND);
        for (int i = 0; i < list.size(); i++) {
            CompoundTag c = list.getCompound(i);
            if (c.hasUUID("id")) {
                p.entries.put(c.getUUID("id"), Entry.load(c));
            }
        }
        return p;
    }

    @Override
    public CompoundTag save(CompoundTag tag) {
        ListTag list = new ListTag();
        entries.forEach((id, e) -> {
            CompoundTag c = e.save();
            c.putUUID("id", id);
            list.add(c);
        });
        tag.put("players", list);
        return tag;
    }
}
'''
JAVA_SOURCES['src/main/java/com/iceage/yantra/progress/PacingEngine.java'] = r'''package com.iceage.yantra.progress;

import com.iceage.yantra.network.CelebratePacket;
import com.iceage.yantra.network.ModNetwork;
import com.iceage.yantra.network.SyncProgressPacket;
import com.iceage.yantra.registry.ModSounds;
import net.minecraft.ChatFormatting;
import net.minecraft.network.chat.Component;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.projectile.FireworkRocketEntity;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraftforge.network.PacketDistributor;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/**
 * The pacing engine: every Yantra pays its frozen blocks in here. Points are capped at 10,000,000 and every
 * tier target crossing is celebrated, which is also the signal Yantras use to switch themselves off.
 */
public final class PacingEngine {
    private static final Map<UUID, Long> PENDING_GAIN = new HashMap<>();

    private PacingEngine() {
    }

    public static long points(MinecraftServer server, UUID owner) {
        if (server == null || owner == null) return 0;
        return IceProgress.get(server).entry(owner).points;
    }

    public static boolean reached(MinecraftServer server, UUID owner, long target) {
        return points(server, owner) >= target;
    }

    /** Adds frozen blocks to the owner's counter. Returns how many were really added (cap aware). */
    public static long award(MinecraftServer server, UUID owner, long amount) {
        if (server == null || owner == null || amount <= 0) return 0;
        IceProgress data = IceProgress.get(server);
        IceProgress.Entry e = data.entry(owner);
        long before = e.points;
        if (before >= Tier.FINAL_TARGET) return 0;
        amount = Math.max(1L, Math.round(amount * (double) e.speed));
        long after = Math.min(Tier.FINAL_TARGET, before + amount);
        e.points = after;
        data.setDirty();
        PENDING_GAIN.merge(owner, after - before, Long::sum);
        ServerPlayer player = server.getPlayerList().getPlayer(owner);
        for (Tier t : Tier.values()) {
            if (before < t.target && after >= t.target) {
                onTargetReached(server, player, t, e);
            }
        }
        return after - before;
    }

    public static void set(MinecraftServer server, UUID owner, long value) {
        IceProgress data = IceProgress.get(server);
        IceProgress.Entry e = data.entry(owner);
        e.points = Math.max(0, Math.min(Tier.FINAL_TARGET, value));
        if (e.points < Tier.FINAL_TARGET) e.climaxDone = false;
        data.setDirty();
        PENDING_GAIN.merge(owner, 0L, Long::sum);
    }

    /** Counter speed multiplier (x0.1 .. x1000); every award is multiplied by it. */
    public static void setSpeed(MinecraftServer server, UUID owner, float speed) {
        IceProgress data = IceProgress.get(server);
        IceProgress.Entry e = data.entry(owner);
        e.speed = Math.max(0.1f, Math.min(1000f, speed));
        data.setDirty();
        PENDING_GAIN.merge(owner, 0L, Long::sum);
    }

    private static void onTargetReached(MinecraftServer server, ServerPlayer player, Tier tier, IceProgress.Entry e) {
        if (player == null) return;
        if (tier == Tier.VAN) {
            if (e.climaxDone) return;
            e.climaxDone = true;
            // finale: Gotiya staggers in with his giant hairdryer to melt the world... and fails (ice never melts)
            com.iceage.yantra.entity.ChillVillagerEntity.spawnHairdryerFinale(player);
            ServerLevel level = player.serverLevel();
            level.playSound(null, player.blockPosition(), ModSounds.FANFARE.get(), SoundSource.PLAYERS, 1.6f, 1.0f);
            for (int i = 0; i < 12; i++) {
                spawnFirework(level, player.getX() + (level.random.nextDouble() - 0.5) * 16, player.getY() + 1,
                        player.getZ() + (level.random.nextDouble() - 0.5) * 16, i);
            }
            return;
        }
        // no banner, no chat: only a soft chime
        player.serverLevel().playSound(null, player.blockPosition(), ModSounds.TARGET_REACHED.get(), SoundSource.PLAYERS, 1.0f, 1.0f);
    }

    public static void spawnFirework(ServerLevel level, double x, double y, double z, int seed) {
        ItemStack rocket = new ItemStack(Items.FIREWORK_ROCKET);
        CompoundTag fw = new CompoundTag();
        ListTag explosions = new ListTag();
        CompoundTag ex = new CompoundTag();
        ex.putByte("Type", (byte) (seed % 5));
        ex.putIntArray("Colors", new int[]{0x7FE6FF, 0xFFFFFF, 0xFF8FC0, 0x3D8BFF});
        ex.putIntArray("FadeColors", new int[]{0xBFF6FF});
        ex.putBoolean("Twinkle", true);
        ex.putBoolean("Trail", true);
        explosions.add(ex);
        fw.put("Explosions", explosions);
        fw.putByte("Flight", (byte) (1 + seed % 2));
        rocket.getOrCreateTag().put("Fireworks", fw);
        FireworkRocketEntity e = new FireworkRocketEntity(level, x, y, z, rocket);
        level.addFreshEntity(e);
    }

    /** Called at the end of every server tick: pushes changed counters to their owners. */
    public static void flush(MinecraftServer server) {
        if (PENDING_GAIN.isEmpty()) return;
        IceProgress data = IceProgress.get(server);
        var it = PENDING_GAIN.entrySet().iterator();
        while (it.hasNext()) {
            var en = it.next();
            ServerPlayer p = server.getPlayerList().getPlayer(en.getKey());
            if (p != null) {
                IceProgress.Entry e = data.entry(en.getKey());
                ModNetwork.CHANNEL.send(PacketDistributor.PLAYER.with(() -> p), new SyncProgressPacket(e.points, e.purchasedMask, en.getValue(), e.speed));
            }
            it.remove();
        }
    }

    public static void sync(ServerPlayer p) {
        IceProgress.Entry e = IceProgress.get(p.server).entry(p.getUUID());
        ModNetwork.CHANNEL.send(PacketDistributor.PLAYER.with(() -> p), new SyncProgressPacket(e.points, e.purchasedMask, 0, e.speed));
    }
}
'''
JAVA_SOURCES['src/main/java/com/iceage/yantra/progress/Tier.java'] = r'''package com.iceage.yantra.progress;

import com.iceage.yantra.registry.ModItems;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.Item;

/** The five Yantras. price = frozen blocks needed to unlock, target = auto-stop threshold. */
public enum Tier {
    GOLA(1, "gola_machine", 0L, 25L, 0xFF5A6E),
    FAN(2, "farrata_fan", 25L, 150L, 0x6FB8FF),
    FRIDGE(3, "retro_fridge", 150L, 1_000L, 0xFF8A8A),
    AC(4, "ac_unit", 1_000L, 50_000L, 0x8FF3FF),
    VAN(5, "ice_cream_van", 50_000L, 10_000_000L, 0xFF9CE0);

    public static final long FINAL_TARGET = 10_000_000L;

    public final int number;
    public final String id;
    public final long price;
    public final long target;
    public final int color;

    Tier(int number, String id, long price, long target, int color) {
        this.number = number;
        this.id = id;
        this.price = price;
        this.target = target;
        this.color = color;
    }

    public Item item() {
        return switch (this) {
            case GOLA -> ModItems.GOLA_MACHINE.get();
            case FAN -> ModItems.FARRATA_FAN.get();
            case FRIDGE -> ModItems.RETRO_FRIDGE.get();
            case AC -> ModItems.AC_UNIT.get();
            case VAN -> ModItems.ICE_CREAM_VAN.get();
        };
    }

    public Component displayName() {
        return Component.translatable("tier.ice_age_yantra." + id);
    }

    public Component gag() {
        return Component.translatable("tier.ice_age_yantra." + id + ".gag");
    }

    public int bit() {
        return 1 << (number - 1);
    }

    public static Tier byNumber(int n) {
        for (Tier t : values()) {
            if (t.number == n) return t;
        }
        return null;
    }

    /** The highest tier whose target the given point total has not reached yet (what you should be running). */
    public static Tier current(long points) {
        for (Tier t : values()) {
            if (points < t.target) return t;
        }
        return VAN;
    }
}
'''
