JAVA_SOURCES['src/main/java/com/iceage/yantra/shop/ShowroomBuilder.java'] = r'''package com.iceage.yantra.shop;

import com.iceage.yantra.block.IcePortalBlock;
import com.iceage.yantra.block.ShowcasePedestalBlock;
import com.iceage.yantra.registry.ModBlocks;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.RotatedPillarBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.DoubleBlockHalf;
import net.minecraft.world.level.saveddata.SavedData;

/**
 * Builds the Frozen Showroom: a crystalline ice hall (frost bricks, frosted glass windows, ice pillars,
 * aurora strips, glacier tile floor), hanging icicle chandeliers, five showcase pedestals with floating
 * Yantras, a glowing title and the return portal.
 */
public final class ShowroomBuilder {
    public static final int VERSION = 5;
    public static final int FLOOR = 63;
    public static final int X0 = -12, X1 = 12, Z0 = -10, Z1 = 22, TOP = 76;
    public static final BlockPos[] PEDESTALS = {
            new BlockPos(-7, 64, 1), new BlockPos(7, 64, 1), new BlockPos(-7, 64, 9), new BlockPos(7, 64, 9), new BlockPos(0, 64, 16)
    };

    private ShowroomBuilder() {
    }

    static class State extends SavedData {
        int version;

        static State load(CompoundTag tag) {
            State s = new State();
            s.version = tag.getInt("version");
            return s;
        }

        @Override
        public CompoundTag save(CompoundTag tag) {
            tag.putInt("version", version);
            return tag;
        }
    }

    public static void ensureBuilt(ServerLevel level) {
        State st = level.getDataStorage().computeIfAbsent(State::load, State::new, "ice_age_yantra_showroom");
        if (st.version < VERSION) {
            build(level);
            st.version = VERSION;
            st.setDirty();
        }
    }

    public static void rebuild(ServerLevel level) {
        build(level);
        State st = level.getDataStorage().computeIfAbsent(State::load, State::new, "ice_age_yantra_showroom");
        st.version = VERSION;
        st.setDirty();
    }

    private static void set(ServerLevel level, int x, int y, int z, BlockState s) {
        level.setBlock(new BlockPos(x, y, z), s, Block.UPDATE_CLIENTS | Block.UPDATE_KNOWN_SHAPE);
    }

    private static void build(ServerLevel level) {
        BlockState air = net.minecraft.world.level.block.Blocks.AIR.defaultBlockState();
        BlockState bricks = ModBlocks.FROST_BRICKS.get().defaultBlockState();
        BlockState glass = ModBlocks.FROSTED_GLASS.get().defaultBlockState();
        BlockState tiles = ModBlocks.GLACIER_TILES.get().defaultBlockState();
        BlockState aurora = ModBlocks.AURORA_ICE.get().defaultBlockState();
        BlockState packed = ModBlocks.PACKED_FROST.get().defaultBlockState();
        BlockState pillar = ModBlocks.ICE_PILLAR.get().defaultBlockState().setValue(RotatedPillarBlock.AXIS, Direction.Axis.Y);

        // clear volume + shell
        for (int x = X0 - 1; x <= X1 + 1; x++) {
            for (int z = Z0 - 1; z <= Z1 + 1; z++) {
                for (int y = FLOOR - 2; y <= TOP + 2; y++) {
                    set(level, x, y, z, air);
                }
            }
        }
        for (int x = X0; x <= X1; x++) {
            for (int z = Z0; z <= Z1; z++) {
                set(level, x, FLOOR - 1, z, packed);
                boolean wall = x == X0 || x == X1 || z == Z0 || z == Z1;
                // floor
                BlockState floor;
                if (wall) floor = packed;
                else if (x == X0 + 1 || x == X1 - 1 || z == Z0 + 1 || z == Z1 - 1) floor = bricks;
                else if (Math.abs(x) <= 1 && z < 14) floor = (Math.abs(x) == 1 ? tiles : aurora);
                else floor = tiles;
                set(level, x, FLOOR, z, floor);
                // ceiling + roof
                boolean strip = !wall && (z % 4 == 0) && Math.abs(x) <= 9;
                set(level, x, TOP, z, strip ? aurora : packed);
                set(level, x, TOP + 1, z, bricks);
                if (!wall) continue;
                for (int y = FLOOR + 1; y < TOP; y++) {
                    BlockState s = bricks;
                    boolean sideWall = x == X0 || x == X1;
                    int along = sideWall ? z : x;
                    boolean isPillar = sideWall ? Math.floorMod(along + 4, 6) == 0 : Math.floorMod(along, 6) == 0;
                    boolean corner = (x == X0 || x == X1) && (z == Z0 || z == Z1);
                    if (corner || isPillar) s = pillar;
                    else if (y >= FLOOR + 3 && y <= FLOOR + 9) s = glass;
                    if (y == TOP - 1 && !(corner || isPillar)) s = aurora;
                    if (y == FLOOR + 1 && !(corner || isPillar)) s = packed;
                    set(level, x, y, z, s);
                }
            }
        }
        // pedestal daises (glowing rings) + pedestals
        for (int i = 0; i < PEDESTALS.length; i++) {
            BlockPos p = PEDESTALS[i];
            int r = i == 4 ? 2 : 1;
            for (int dx = -r; dx <= r; dx++) {
                for (int dz = -r; dz <= r; dz++) {
                    set(level, p.getX() + dx, FLOOR, p.getZ() + dz, (Math.abs(dx) == r || Math.abs(dz) == r) ? aurora : bricks);
                }
            }
            level.setBlock(p, ModBlocks.SHOWCASE_PEDESTAL.get().defaultBlockState().setValue(ShowcasePedestalBlock.TIER, i + 1), Block.UPDATE_ALL);
        }
        // chandeliers
        int[][] ch = {{-6, -4}, {6, -4}, {-6, 5}, {6, 5}, {-6, 13}, {6, 13}, {0, 1}, {0, 9}, {0, 19}};
        for (int[] c : ch) {
            level.setBlock(new BlockPos(c[0], TOP - 1, c[1]), ModBlocks.ICICLE_CHANDELIER.get().defaultBlockState(), Block.UPDATE_ALL);
        }
        // title sign above the van stage
        level.setBlock(new BlockPos(0, FLOOR + 8, 20), ModBlocks.SHOP_SIGN.get().defaultBlockState(), Block.UPDATE_ALL);
        // return portal at the entrance, facing into the hall
        BlockState portal = ModBlocks.ICE_PORTAL.get().defaultBlockState().setValue(IcePortalBlock.FACING, Direction.SOUTH);
        level.setBlock(new BlockPos(0, FLOOR + 1, Z0 + 1), portal.setValue(IcePortalBlock.HALF, DoubleBlockHalf.LOWER), Block.UPDATE_ALL);
        level.setBlock(new BlockPos(0, FLOOR + 2, Z0 + 1), portal.setValue(IcePortalBlock.HALF, DoubleBlockHalf.UPPER), Block.UPDATE_ALL);
        // arrival pad: a solid glowing dais whose top is exactly Y = 65.0, centred on X = 0.5, Z = 0.5
        for (int dx = -1; dx <= 1; dx++) {
            for (int dz = -1; dz <= 1; dz++) {
                set(level, dx, FLOOR, dz, packed);
                set(level, dx, FLOOR + 1, dz, (dx == 0 && dz == 0) ? aurora : bricks);
            }
        }
        // frost carpet in front of the portal
        for (int dx = -1; dx <= 1; dx++) {
            for (int dz = 2; dz <= 4; dz++) {
                set(level, dx, FLOOR, Z0 + dz, dx == 0 ? aurora : tiles);
            }
        }
    }
}
'''
JAVA_SOURCES['src/main/java/com/iceage/yantra/shop/ShowroomDimension.java'] = r'''package com.iceage.yantra.shop;

import com.iceage.yantra.IceAgeYantra;
import com.iceage.yantra.progress.IceProgress;
import com.iceage.yantra.registry.ModSounds;
import net.minecraft.ChatFormatting;
import net.minecraft.core.BlockPos;
import net.minecraft.core.registries.Registries;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceKey;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.Vec3;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/** The dedicated Frozen Showroom dimension and the teleport logic of the ice portals. */
public final class ShowroomDimension {
    public static final ResourceKey<Level> KEY = ResourceKey.create(Registries.DIMENSION, IceAgeYantra.id("frozen_showroom"));
    public static final Vec3 ARRIVAL = new Vec3(0.5, 65.0, 0.5);
    private static final Map<UUID, Long> COOLDOWN = new HashMap<>();

    private ShowroomDimension() {
    }

    public static boolean isShowroom(Level level) {
        return level.dimension() == KEY;
    }

    /** Stepping into an ice portal. */
    public static void enterPortal(ServerPlayer player) {
        long now = player.server.getTickCount();
        Long until = COOLDOWN.get(player.getUUID());
        if (until != null && now < until) {
            COOLDOWN.put(player.getUUID(), now + 20);
            return;
        }
        COOLDOWN.put(player.getUUID(), now + 60);
        toggle(player);
    }

    public static void toggle(ServerPlayer player) {
        COOLDOWN.put(player.getUUID(), (long) player.server.getTickCount() + 60);
        if (isShowroom(player.level())) goBack(player);
        else goToShowroom(player);
    }

    public static void goToShowroom(ServerPlayer player) {
        MinecraftServer server = player.server;
        ServerLevel shop = server.getLevel(KEY);
        if (shop == null) {
            player.displayClientMessage(Component.literal("Frozen Showroom dimension is missing (datapack disabled?)").withStyle(ChatFormatting.RED), false);
            return;
        }
        IceProgress data = IceProgress.get(server);
        IceProgress.Entry e = data.entry(player.getUUID());
        Vec3 look = player.getLookAngle().multiply(1, 0, 1);
        if (look.lengthSqr() < 1e-4) look = new Vec3(0, 0, 1);
        look = look.normalize();
        e.returnDim = player.level().dimension();
        e.returnPos = player.position().subtract(look.scale(1.6));
        e.returnYaw = player.getYRot() + 180f;
        data.setDirty();
        shop.getChunk(0, 0);
        ShowroomBuilder.ensureBuilt(shop);
        safeTeleport(player, shop, ARRIVAL, 0f, 5f);
        shop.playSound(null, BlockPos.containing(ARRIVAL), ModSounds.PORTAL_WHOOSH.get(), SoundSource.PLAYERS, 1.0f, 1.0f);
    }

    /** Teleports with zero velocity and no accumulated fall damage. */
    public static void safeTeleport(ServerPlayer player, ServerLevel level, Vec3 pos, float yaw, float pitch) {
        player.stopRiding();
        if (player.level() != level) {
            // tell the client to skip the "Loading terrain" screen for this hop
            com.iceage.yantra.network.ModNetwork.CHANNEL.send(net.minecraftforge.network.PacketDistributor.PLAYER.with(() -> player),
                    new com.iceage.yantra.network.CelebratePacket(com.iceage.yantra.network.CelebratePacket.SEAMLESS, 0));
        }
        player.setDeltaMovement(Vec3.ZERO);
        player.fallDistance = 0f;
        player.teleportTo(level, pos.x, pos.y, pos.z, yaw, pitch);
        player.setDeltaMovement(Vec3.ZERO);
        player.fallDistance = 0f;
        player.hurtMarked = true;
        player.connection.resetPosition();
    }

    /** Finds solid ground with two free blocks above it, near the remembered spot (never mid-air, never inside blocks). */
    public static Vec3 groundAt(ServerLevel level, Vec3 near) {
        int x = net.minecraft.util.Mth.floor(near.x), z = net.minecraft.util.Mth.floor(near.z);
        level.getChunk(x >> 4, z >> 4);
        int startY = Math.min(level.getMaxBuildHeight() - 3, net.minecraft.util.Mth.floor(near.y) + 3);
        for (int y = startY; y > Math.max(level.getMinBuildHeight(), startY - 48); y--) {
            BlockPos g = new BlockPos(x, y, z);
            if (level.getBlockState(g).getCollisionShape(level, g).isEmpty()) continue;
            if (!level.getBlockState(g.above()).getCollisionShape(level, g.above()).isEmpty()) continue;
            if (!level.getBlockState(g.above(2)).getCollisionShape(level, g.above(2)).isEmpty()) continue;
            if (level.getBlockState(g).getBlock() instanceof com.iceage.yantra.block.IcePortalBlock) continue;
            double top = g.getY() + level.getBlockState(g).getCollisionShape(level, g).max(net.minecraft.core.Direction.Axis.Y);
            return new Vec3(x + 0.5, top, z + 0.5);
        }
        BlockPos h = level.getHeightmapPos(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, new BlockPos(x, 0, z));
        return Vec3.atBottomCenterOf(h);
    }

    /** Void safety net: anyone below the showroom floor is put straight back on the arrival pad. */
    public static void guard(ServerPlayer player) {
        if (isShowroom(player.level()) && player.getY() < ShowroomBuilder.FLOOR - 4) {
            safeTeleport(player, (ServerLevel) player.level(), ARRIVAL, 0f, 5f);
        }
    }

    public static void goBack(ServerPlayer player) {
        MinecraftServer server = player.server;
        IceProgress.Entry e = IceProgress.get(server).entry(player.getUUID());
        ServerLevel target = e.returnDim != null ? server.getLevel(e.returnDim) : null;
        Vec3 pos = e.returnPos;
        float yaw = e.returnYaw;
        if (target == null || pos == null) {
            target = server.overworld();
            BlockPos spawn = target.getSharedSpawnPos();
            pos = Vec3.atBottomCenterOf(target.getHeightmapPos(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, spawn));
            yaw = 0f;
        }
        pos = groundAt(target, pos);
        safeTeleport(player, target, pos, yaw, 0f);
        target.playSound(null, BlockPos.containing(pos), ModSounds.PORTAL_WHOOSH.get(), SoundSource.PLAYERS, 1.0f, 0.8f);
    }
}
'''


